/**
 * Founder-approved episode backfill (2026-10-30): appends the canonical
 * per-turn rows listed in RECEIPT_PATH to their episode row, oldest first,
 * then re-embeds the episode so its search chunks include them.
 *
 * Inert until a receipt generated by
 * server/scripts/generate-episode-backfill-receipt.ts is committed and
 * approved. Idempotent: every entry is decided against the locked episode
 * content (server/services/episode-backfill.ts), so a turn already present is
 * never appended again and a re-run after success appends nothing.
 *
 * Fail-closed and in order: the first entry whose row is missing or whose
 * bytes no longer match the approved hash stops the run with nothing after it
 * appended, so the episode never gains a newer turn before an older one. That
 * is reported, never forced.
 *
 * Re-embed: the projection append path does not re-embed, so the episode's
 * conversation_chunk embeddings would stay stale. Once every entry is present,
 * reembedConversationMemory() runs and is awaited. Unchanged chunks are
 * skipped by content hash, so re-running is cheap, and a failure is reported
 * (not thrown, so a provider outage cannot block a release) and retried on the
 * next deploy. Its outcome is in the detail line either way.
 */
import { existsSync, readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import type { Pool } from '@neondatabase/serverless';
import type { DataOpResult } from '../run-data-ops';
import {
  decideEntry, episodeBackfillReceiptProblem, type EpisodeBackfillReceipt,
} from '../../server/services/episode-backfill';

export const RECEIPT_PATH = join(dirname(fileURLToPath(import.meta.url)), 'backfill-episode-turns.receipt.json');

/** The connection surface applyBackfill needs; a real Pool provides it. */
export interface BackfillPool {
  connect(): Promise<{ query(sql: string, params?: unknown[]): Promise<{ rows: any[] }>; release(): void }>;
}

export interface BackfillCounts { appended: number; present: number; stoppedAt: string | null; stopReason: string | null }

/** Apply one approved receipt. Exported so the transaction rules are tested with a fake pool. */
export async function applyBackfill(pool: BackfillPool, receipt: EpisodeBackfillReceipt): Promise<BackfillCounts> {
  const problem = episodeBackfillReceiptProblem(receipt);
  if (problem) throw new Error(`episode backfill receipt refused: ${problem}`);
  const counts: BackfillCounts = { appended: 0, present: 0, stoppedAt: null, stopReason: null };
  for (const entry of receipt.entries) {
    const client = await pool.connect();
    try {
      await client.query('BEGIN');
      const episode = (await client.query(
        'SELECT title, content FROM conversation_memories WHERE id = $1 FOR UPDATE', [receipt.episodeId],
      )).rows[0];
      if (!episode || typeof episode.content !== 'string') {
        await client.query('ROLLBACK');
        counts.stoppedAt = entry.rowId; counts.stopReason = 'episode row missing';
        return counts;
      }
      if (episode.title !== receipt.episodeTitle) {
        await client.query('ROLLBACK');
        counts.stoppedAt = entry.rowId; counts.stopReason = 'episode title differs from the receipt';
        return counts;
      }
      const row = (await client.query('SELECT content FROM conversation_memories WHERE id = $1', [entry.rowId])).rows[0] ?? null;
      const outcome = decideEntry(entry, row, episode.content);
      if (outcome.status === 'append') {
        await client.query('UPDATE conversation_memories SET content = content || $2 WHERE id = $1', [receipt.episodeId, outcome.text]);
        counts.appended++;
      } else if (outcome.status === 'present') {
        counts.present++;
      } else {
        await client.query('ROLLBACK');
        counts.stoppedAt = entry.rowId; counts.stopReason = outcome.status;
        return counts;
      }
      await client.query('COMMIT');
    } catch (e) {
      await client.query('ROLLBACK').catch(() => undefined);
      throw e;
    } finally {
      client.release();
    }
  }
  return counts;
}

export function describe(counts: BackfillCounts, total: number, reembed: string): string {
  const stop = counts.stoppedAt ? `; STOPPED at ${counts.stoppedAt} (${counts.stopReason}), later entries not appended` : '';
  return `episode backfill: appended ${counts.appended}, already present ${counts.present} of ${total}${stop}; re-embed: ${reembed}`;
}

export async function run(pool: Pool): Promise<DataOpResult> {
  if (!existsSync(RECEIPT_PATH)) return { applied: false, detail: 'no approved episode backfill receipt; nothing to do' };
  const receipt = JSON.parse(readFileSync(RECEIPT_PATH, 'utf8')) as EpisodeBackfillReceipt;
  const counts = await applyBackfill(pool as unknown as BackfillPool, receipt);
  let reembed = 'skipped: not every listed turn is present yet';
  if (!counts.stoppedAt) {
    try {
      const { reembedConversationMemory } = await import('../../server/scripts/reembed-memory');
      await reembedConversationMemory(receipt.episodeId);
      reembed = 'done';
    } catch (e: any) {
      reembed = `FAILED, will retry on the next deploy: ${e?.message ?? e}`;
    } finally {
      // server/db opens its own pool on import; close it so the pre-deploy
      // process exits promptly instead of waiting on idle connections.
      const { closeDbConnections } = await import('../../server/db');
      await closeDbConnections().catch(() => undefined);
    }
  }
  return { applied: counts.appended > 0, detail: describe(counts, receipt.entries.length, reembed) };
}
